            ['TPL-FURNITURE-02', 'furniture', 'เก้าอี้สำนักงานมีล้อ', 'ตัว', 30, '2 ปี', 'มอก. / TIS 1285', 2800, 21, '<ol><li>โครงพนักพิงตาข่าย (Mesh) หรือผ้า ระบายอากาศดี</li><li>ปรับระดับความสูงที่นั่งได้ (Gas Lift)</li><li>ล้อแบบ Nylon 5 ขา เส้นผ่าศูนย์กลาง ≥ 65 cm</li><li>แขนพักแขนปรับระดับได้</li><li>รองรับน้ำหนัก ≥ 100 กก.</li><li>ปรับเอนพนักพิงได้ พร้อม Lumbar Support</li></ol>'],
            ['TPL-FURNITURE-03', 'furniture', 'ตู้เก็บเอกสารโลหะ 4 ลิ้นชัก', 'ตู้', 30, '2 ปี', 'มอก.', 3500, 22, '<ol><li>วัสดุเหล็ก Coldrolled Steel หนา ≥ 0.8 mm</li><li>ขนาด กว้าง 46 cm × ลึก 62 cm × สูง 132 cm (±2 cm)</li><li>ลิ้นชัก 4 ชั้น พร้อมรางลื่น Slide Rail</li><li>มีระบบล็อกกุญแจทุกลิ้นชัก (Central Lock)</li><li>พ่นสีฝุ่น Powder Coat กันสนิม</li><li>รองรับแฟ้มแขวน Letter/A4</li></ol>'],
            ['TPL-FURNITURE-04', 'furniture', 'ชั้นวางของสำนักงาน (Shelf)', 'ชุด', 30, '1 ปี', 'มอก.', 3500, 23, '<ol><li>วัสดุเหล็กโครงสร้าง หนา ≥ 1.0 mm</li><li>จำนวนชั้น ≥ 5 ชั้น ปรับระดับได้</li><li>ขนาด กว้าง ≥ 90 cm × ลึก ≥ 40 cm × สูง ≥ 180 cm</li><li>รับน้ำหนักต่อชั้น ≥ 50 กก.</li><li>พ่นสีฝุ่นกันสนิม</li><li>ประกอบ-ถอดได้ ไม่ต้องใช้เครื่องมือพิเศษ</li></ol>'],
            ['TPL-FURNITURE-05', 'furniture', 'โต๊ะนักเรียน-เก้าอี้นักเรียน', 'ชุด', 30, '3 ปี', 'มอก.1494', 3500, 24, '<ol><li>โต๊ะ: พื้นท็อปเมลามีน ขนาด 40×60 cm หนา ≥ 18mm</li><li>โครงโต๊ะเหล็กกลม เส้นผ่านศูนย์กลาง ≥ 25mm</li><li>เก้าอี้: ที่นั่งและพนักพิงพลาสติก PP เกรด A</li><li>โครงเก้าอี้เหล็กกลมชุบโครเมียม/พ่นสี</li><li>ปรับระดับโต๊ะได้ (สำหรับ รร.ประถม/มัธยม ตามที่กำหนด)</li><li>ขาโต๊ะและเก้าอี้มียาง Anti-Slip กันลื่น</li></ol>'],
            ['TPL-FURNITURE-06', 'furniture', 'ตู้เก็บของอเนกประสงค์ (Locker)', 'ตู้', 30, '2 ปี', null, 3500, 25, '<ol><li>วัสดุเหล็กคุณภาพสูง พ่นสีฝุ่น</li><li>ขนาด กว้าง ≥ 30 cm × ลึก ≥ 45 cm × สูง ≥ 180 cm</li><li>จำนวนช่องล็อค ≥ 6 ช่อง พร้อมกุญแจแต่ละช่อง</li><li>มีช่องระบายอากาศ</li><li>ขาปรับระดับ ≥ 4 จุด</li></ol>'],
            ['TPL-VEHICLE-01', 'vehicle', 'รถยนต์นั่งราชการ (Sedan)', 'คัน', 90, '3 ปี หรือ 100,000 กม.', 'มาตรฐานสิ่งแวดล้อม Euro 4/5', 95000, 26, '<ol><li>เครื่องยนต์ขนาดไม่เกิน 1,800 cc (ตามที่กำหนด)</li><li>ระบบเกียร์อัตโนมัติ Automatic Transmission</li><li>ประหยัดน้ำมัน ≥ 15 กม./ลิตร (ผสม)</li><li>มีระบบ ABS, EBD, Airbag คู่หน้าอย่างน้อย</li><li>ระบบ Air Conditioner ทั้งหน้าและหลัง</li><li>รองรับการประดับเครื่องหมายราชการ</li><li>สีตามที่หน่วยงานกำหนด (ขาวหรือเงิน)</li></ol>'],
            ['TPL-VEHICLE-02', 'vehicle', 'รถกระบะขับเคลื่อน 2/4 ล้อ', 'คัน', 90, '3 ปี หรือ 100,000 กม.', 'มาตรฐาน Euro 4', 95000, 27, '<ol><li>เครื่องยนต์ดีเซล ≥ 2,400 cc Common Rail</li><li>กำลังเครื่องยนต์ ≥ 150 แรงม้า</li><li>ระบบเกียร์ Manual 5 สปีด หรือ Automatic</li><li>ระบบขับเคลื่อน 2WD หรือ 4WD (ตามที่กำหนด)</li><li>น้ำหนักบรรทุก ≥ 1,000 กก.</li><li>มีระบบ ABS, Airbag</li><li>Air Conditioner</li></ol>'],
            ['TPL-VEHICLE-03', 'vehicle', 'รถจักรยานยนต์ราชการ', 'คัน', 45, '2 ปี หรือ 20,000 กม.', 'มอก.341 / Euro 3', 55000, 28, '<ol><li>เครื่องยนต์ ≥ 100 cc ≤ 150 cc</li><li>ระบบฉีดน้ำมัน (Fuel Injection) หรือคาร์บูเรเตอร์</li><li>ระบบเบรก Disc Brake หน้า, Drum หลัง (CBS)</li><li>สีและมาตรฐานราชการ</li><li>มีกระจกมองหลัง 2 ด้าน, แตรไฟฟ้า, ไฟหน้า/ท้าย</li></ol>'],
            ['TPL-CAMERA-01', 'camera', 'กล้องวงจรปิด IP Camera', 'ตัว', 30, '2 ปี', 'CE / FCC / IP66', 4500, 29, '<ol><li>ความละเอียด ≥ 2 MP (Full HD 1080p) หรือ 4 MP</li><li>ชนิด Dome หรือ Bullet (ตามที่กำหนด)</li><li>มาตรฐานกันน้ำ/กันฝุ่น ≥ IP66</li><li>ระบบมองเห็นกลางคืน IR ≥ 30 เมตร</li><li>มุมมองภาพ ≥ 90 องศา</li><li>รองรับ PoE (Power over Ethernet)</li><li>รองรับ H.265/H.264 Compression</li></ol>'],
            ['TPL-CAMERA-02', 'camera', 'กล้องถ่ายภาพนิ่ง DSLR/Mirrorless', 'ชุด', 30, '1 ปี', 'CE / FCC', 25000, 30, '<ol><li>ความละเอียดเซนเซอร์ ≥ 24 MP</li><li>ระบบ Autofocus ≥ 20 จุด</li><li>ถ่ายภาพต่อเนื่อง ≥ 5 fps</li><li>บันทึกวิดีโอ ≥ Full HD 1080p/30fps</li><li>จอ LCD ≥ 3 นิ้ว (Tilt/Touch Screen)</li><li>รองรับการ์ดหน่วยความจำ SD/SDHC/SDXC</li><li>มาพร้อม Lens ≥ 18-55mm Kit</li><li>แบตเตอรี่ ≥ 300 ช็อต/ชาร์จ</li></ol>'],
            ['TPL-CAMERA-03', 'camera', 'กล้องบันทึกวิดีโอ Camcorder', 'เครื่อง', 30, '1 ปี', 'CE / FCC', 12000, 31, '<ol><li>ความละเอียด ≥ Full HD 1080p หรือ 4K</li><li>ซูม Optical ≥ 20x</li><li>ระบบ Image Stabilizer อิเล็กทรอนิกส์/ออปติคัล</li><li>บันทึกลง SD Card/Memory Stick</li><li>จอ LCD ≥ 3 นิ้ว Flip/Rotatable</li><li>มีไมโครโฟนในตัวและพอร์ต External Mic</li><li>แบตเตอรี่ ≥ 90 นาที ต่อเนื่อง</li></ol>'],
            ['TPL-CAMERA-04', 'camera', 'ระบบกล้องวงจรปิดครบชุด', 'ชุด', 45, '2 ปี', 'CE / IP66', 4500, 32, '<ol><li>กล้อง IP Camera ≥ 4 MP จำนวน ≥ 8 ตัว (ตามที่กำหนด)</li><li>NVR รองรับ ≥ 16 ช่อง พร้อม HDD ≥ 2 TB</li><li>สาย LAN CAT6 พร้อมอุปกรณ์ PoE Switch</li><li>จอ Monitor ≥ 24 นิ้ว Full HD</li><li>UPS สำรองไฟ ≥ 30 นาที</li><li>ติดตั้ง เดินสาย ตั้งค่าระบบ ให้ดูภาพจาก Mobile App</li><li>รับประกันระบบ ≥ 2 ปี Onsite</li></ol>'],
            ['TPL-MEDICAL-01', 'medical', 'เครื่องวัดความดันโลหิตดิจิทัล', 'เครื่อง', 15, '2 ปี', 'มอก. / CE / ISO 81060', 3500, 33, '<ol><li>ชนิดแขน (Upper Arm) หรือข้อมือ (ตามที่กำหนด)</li><li>ช่วงวัด: ความดัน 0-299 mmHg ชีพจร 40-200 bpm</li><li>ความแม่นยำ: ±3 mmHg หรือ ±2%</li><li>หน้าจอ LCD ขนาดใหญ่ อ่านง่าย</li><li>บันทึกผล ≥ 60 ครั้ง</li><li>พลังงาน แบตเตอรี่ AA × 4 หรือ USB</li><li>มี CE Mark และผ่านการรับรอง อย.</li></ol>'],
            ['TPL-MEDICAL-02', 'medical', 'เครื่องชั่งน้ำหนักดิจิทัลพร้อมวัดส่วนสูง', 'เครื่อง', 15, '2 ปี', 'มอก. / CE', 5500, 34, '<ol><li>ความสามารถรับน้ำหนัก ≥ 200 กก.</li><li>ความละเอียด 0.1 กก.</li><li>ช่วงวัดส่วนสูง 60-200 cm ความละเอียด 0.1 cm</li><li>จอ LCD แสดงผลน้ำหนัก+ส่วนสูง</li><li>คำนวณค่า BMI ได้</li><li>พลังงาน ไฟฟ้า 220V พร้อมสาย AC</li></ol>'],
            ['TPL-MEDICAL-03', 'medical', 'ตู้ยาพยาบาล First Aid Cabinet', 'ตู้', 15, '1 ปี', null, 15000, 35, '<ol><li>วัสดุเหล็กหรือพลาสติก ABS แข็งแรง</li><li>ขนาดเหมาะสมสำหรับ ≥ 30 ชั้นของยาและอุปกรณ์</li><li>มีแผงชั้นปรับระดับได้</li><li>ประตูบานพับพร้อมกุญแจ</li><li>มีสัญลักษณ์กากบาทสีแดงชัดเจน</li><li>บรรจุอุปกรณ์ปฐมพยาบาลครบชุด (ตามรายการที่กำหนด)</li></ol>'],
            ['TPL-ELECTRICAL-01', 'electrical', 'ตู้ควบคุมไฟฟ้า (MDB/DB)', 'ตู้', 45, '2 ปี', 'มอก.824 / IEC 61439', 8500, 36, '<ol><li>ตู้โลหะ IP54 พร้อม Main Breaker ขนาดตามที่ออกแบบ</li><li>Circuit Breaker ลูกย่อยตามจำนวนที่กำหนด</li><li>มี Surge Protection Device (SPD) ≥ Class II</li><li>Busbar ทองแดง ≥ 60A</li><li>พร้อมสายไฟภายใน H07V-K หรือเทียบเท่า</li><li>ติดตั้งและทดสอบระบบ พร้อม As-Built Drawing</li></ol>'],
            ['TPL-ELECTRICAL-02', 'electrical', 'โคมไฟ LED แบบฝังฝ้า', 'โคม', 15, '3 ปี', 'มอก.236 / Energy Star', 8500, 37, '<ol><li>กำลังไฟ ≤ 18W (แทน T8 36W เดิม) หรือตามที่กำหนด</li><li>ฟลักซ์การส่องสว่าง ≥ 1,800 Lm</li><li>ค่า CRI ≥ 80</li><li>อุณหภูมิสี 4000K-6500K (Neutral/Cool White)</li><li>อายุการใช้งาน ≥ 25,000 ชั่วโมง</li><li>ไม่มีปรอท (Mercury Free)</li><li>รองรับแรงดัน 220V/50Hz ±10%</li></ol>'],
            ['TPL-ELECTRICAL-03', 'electrical', 'ปลั๊กไฟมาตรฐาน (Power Strip)', 'อัน', 15, '1 ปี', 'มอก.2432', 8500, 38, '<ol><li>ช่องเสียบ ≥ 4 ช่อง แบบ 3 ขา (Universal)</li><li>มี Switch ควบคุม On/Off พร้อมไฟแสดงสถานะ</li><li>Surge Protector ≥ 250J</li><li>สาย ≥ 3 เมตร หน้าตัด ≥ 0.75 sq.mm</li><li>มอก.2432 รับรอง</li><li>รับกระแสสูงสุด ≥ 10A</li></ol>'],
            ['TPL-ELECTRICAL-04', 'electrical', 'ไฟฉุกเฉิน Emergency Light', 'ดวง', 15, '2 ปี', 'มอก.2295', 8500, 39, '<ol><li>กำลังไฟ LED ≥ 5W ความสว่าง ≥ 300 Lm</li><li>แบตเตอรี่สำรอง Ni-Cd หรือ Li-ion</li><li>เวลาสำรองไฟ ≥ 2 ชั่วโมง</li><li>Charge อัตโนมัติเมื่อมีไฟปกติ</li><li>ทดสอบ Self-Test ได้</li><li>มอก.2295 รับรอง</li></ol>'],
            ['TPL-TOOLS-01', 'tools', 'สว่านไฟฟ้าแบบกระแทก', 'ตัว', 15, '1 ปี', 'มอก. / CE', 2800, 40, '<ol><li>กำลังมอเตอร์ ≥ 600W</li><li>ความเร็วรอบ ≥ 2,800 rpm</li><li>ขนาดดอกสว่านรองรับ ≥ 13 mm</li><li>ระบบ Hammer Drill (ตอก+เจาะ) และ Drill (เจาะอย่างเดียว)</li><li>ปรับความเร็ว 2 ระดับ</li><li>มือจับยาง Anti-Vibration</li></ol>'],
            ['TPL-TOOLS-02', 'tools', 'เครื่องมัลติมิเตอร์ดิจิทัล', 'เครื่อง', 15, '1 ปี', 'CE / CAT III 600V', 4500, 41, '<ol><li>วัดแรงดัน AC/DC ≥ 600V</li><li>วัดกระแส AC/DC ≥ 10A</li><li>วัดความต้านทาน ≥ 40 MΩ</li><li>วัดความจุ, ความถี่, อุณหภูมิ</li><li>ค่า True RMS</li><li>Safety Category CAT III 600V</li><li>พร้อมสายวัด Test Leads และ Case</li></ol>'],
            ['TPL-TOOLS-03', 'tools', 'กล่องเครื่องมือช่างครบชุด', 'ชุด', 15, '1 ปี', null, 4500, 42, '<ol><li>ประแจปากตาย ชุด 6-24mm ≥ 8 ตัว</li><li>ประแจแหวน ≥ 8 ตัว</li><li>ไขควง + และ - ≥ 6 ตัว</li><li>คีมตัด/คีมปากแหลม/คีมล็อค ≥ 3 ตัว</li><li>ค้อน ≥ 1 ตัว, เทปวัด ≥ 5 เมตร</li><li>กล่องใส่เครื่องมือพลาสติก ABS</li><li>วัสดุCr-V/S2 Steel ชุบแข็ง</li></ol>'],
            ['TPL-EDUCATION-01', 'education', 'ชุดอุปกรณ์วิทยาศาสตร์ (Science Kit)', 'ชุด', 30, '1 ปี', 'มอก. / CE (เคมีภัณฑ์ผ่าน อย.)', 5500, 43, '<ol><li>กล้องจุลทรรศน์ชนิดประกอบ กำลังขยาย 40x-400x ≥ 1 ตัว</li><li>ชุดแก้วทดลอง (Beaker, Flask, Test Tube) ≥ 20 ชิ้น</li><li>เตรียมสารเคมีพื้นฐาน (ตามรายการ) ครบชุด</li><li>แผ่นกระจก Slide ≥ 50 แผ่น</li><li>อุปกรณ์วัดอุณหภูมิ, ชั่งน้ำหนัก</li><li>คู่มือการทดลองภาษาไทย</li></ol>'],
            ['TPL-EDUCATION-02', 'education', 'ลูกบาสเกตบอลมาตรฐาน FIBA', 'ลูก', 15, '6 เดือน', 'FIBA Approved', 850, 44, '<ol><li>เส้นรอบวง 749-780 mm (Size 7 ผู้ชาย) / 724-737 mm (Size 6 หญิง)</li><li>น้ำหนัก 567-650 g (Size 7) / 510-567 g (Size 6)</li><li>วัสดุหนังสังเคราะห์หรือยางคุณภาพสูง</li><li>ความดันอากาศมาตรฐาน 0.49-0.69 bar</li><li>ผ่านการรับรอง FIBA หรือเทียบเท่า</li></ol>'],
            ['TPL-EDUCATION-03', 'education', 'โต๊ะปิงปองมาตรฐาน', 'ตัว', 30, '2 ปี', 'ITTF Approved', 3500, 45, '<ol><li>ขนาด 274×152.5×76 cm (มาตรฐาน ITTF)</li><li>พื้นโต๊ะ Chipboard หรือ MDF หนา ≥ 22 mm</li><li>ผิวหน้าสีเขียว/น้ำเงิน เส้นขาว กันความชื้น</li><li>ขาโต๊ะเหล็กกลม อ่อนตัวได้ Anti-Vibration</li><li>ระบบพับเก็บได้ พร้อมล้อเลื่อนล็อค</li><li>มาพร้อมตาข่ายและที่จับตาข่าย</li></ol>'],
            ['TPL-EDUCATION-04', 'education', 'เครื่องดนตรีไทย (ชุด)', 'ชุด', 30, '1 ปี', null, 5500, 46, '<ol><li>ระนาดเอก ≥ 1 ราง พร้อมไม้และรางรับ</li><li>ระนาดทุ้ม ≥ 1 ราง</li><li>ฆ้องวงใหญ่/เล็ก ≥ 1 วง</li><li>ตีนตัก/กลองทัด ≥ 1 ชุด</li><li>ขลุ่ยเพียงออ/ขลุ่ยหลิบ ≥ 2 เลา</li><li>วัสดุไม้คุณภาพ (ไม้สัก/ไม้ชิงชัน) งานฝีมือ</li></ol>'],
