    public function safeUp(): void
    {
        $now = date('Y-m-d H:i:s');
        $data = [];
        foreach ($this->rows() as $r) {
            [$code, $cat, $title, $unit, $days, $warranty, $std, $refPrice, $sort, $spec] = $r;
            $data[] = [$code, $cat, $title, $unit, $days, $warranty, $std, $spec, $refPrice, 1, $sort, $now, $now];
        }

        $this->batchInsert('{{%purchase_tor_template}}', [
            'code',
            'category',
            'title',
            'unit_name',
            'delivery_days',
            'warranty',
            'standard',
            'spec',
            'ref_price',
            'active',
            'sort_order',
            'created_at',
            'updated_at',
        ], $data);
    }

    public function safeDown(): void
    {
        // ลบเฉพาะแม่แบบชุดตั้งต้น — แม่แบบที่หน่วยงานเพิ่มเองภายหลังไม่มีรหัสขึ้นต้น TPL- จึงไม่ถูกลบ
        $this->delete('{{%purchase_tor_template}}', ['like', 'code', 'TPL-%', false]);
    }
